sys_variable_value.value:
(function execute(inputs, outputs) {

   var useraddress = JSON.parse(inputs.input);   
   
    var gr = new GlideRecord('x_vuram_financia_0_fcc_kyc_individual_details');
    if (gr.get(inputs.sysId)) { 
        gr.address_line = useraddress.address;
        
        gr.city = useraddress.city;
        gr.postcode = useraddress.post_code;
        gr.country_of_nationality = useraddress.country_of_nationality;  
        gr.country_of_residence = useraddress.country_of_residence;
        gr.poa_doc_name = useraddress.document_name;
        gr.poa_identity_doc_type = useraddress.document_type;
        gr.poa_doc_id_no = useraddress.document_number;
        gr.mobile_contact= useraddress.mobile_number;
        gr.home_contact = useraddress.mobile_number;
        gr.mobile = useraddress.mobile_number;

        var gd = new GlideDate();
        gd.setValue(useraddress.issue_date);  // Works in scoped apps
        gr.poa_doc_issued_date = gd;

        var gd = new GlideDate();
        gd.setValue(useraddress.document_expiry_date);  // Works in scoped apps
        gr.poa_doc_expiry_date = gd;

        gr.poa_doc_issued_by = useraddress.document_issued_by;
        gr.poa_doc_place_of_issuance = useraddress.document_place_of_issuance;
        gr.update();
    } else {
        gs.error('No record found with sys_id: ' + inputs.sysId);
    }

})(inputs, outputs);

